import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Plan — FR 3.2.5: Change Password","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-5-change-password/plan.md","filePath":"feature/srs/01-authentication/3-2-5-change-password/plan.md"}'),d={name:"feature/srs/01-authentication/3-2-5-change-password/plan.md"};function r(c,e,n,i,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-5-change-password" tabindex="-1">Plan — FR 3.2.5: Change Password <a class="header-anchor" href="#plan-—-fr-3-2-5-change-password" aria-label="Permalink to &quot;Plan — FR 3.2.5: Change Password&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Authenticated password change (<code>POST /api/v1/auth/change-password</code>, plus OTP-verified change/set-password support), current password verification, password reuse guard (<code>BR-08</code>), and other-device refresh token invalidation.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>JwtAuthFilterGatewayFilterFactory.java</code> (enforces valid <code>Bearer</code> JWT on <code>/api/v1/auth/change-password*</code> and <code>/set-password</code>)</td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/auth/AuthController.java</code> (<code>changePassword</code>, <code>sendPasswordChangeOtp</code>, <code>changePasswordWithOtp</code>, <code>setPassword</code>, <code>revokeOtherSessions</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/auth/AuthServiceImpl.java</code> (<code>changePassword</code>, <code>setPassword</code>, <code>revokeOtherSessions</code>)</td></tr><tr><td style="text-align:left;"><strong>DTOs &amp; Errors</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>ChangePasswordRequest(currentPassword, newPassword)</code>, <code>ErrorCode</code> (<code>WRONG_CURRENT_PASSWORD</code>, <code>SAME_AS_CURRENT_PASSWORD</code>, <code>VALIDATION_ERROR</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>UserRepository.java</code>, <code>UserRefreshTokenRepository.java</code>, <code>AuditLogRepository.java</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/security/index.tsx</code>, <code>src/pages/security/components/{ChangePasswordCard,ActiveSessionsCard}.tsx</code>, <code>src/services/authService.ts</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>src/screens/settings/SecuritySettingsScreen.tsx</code>, <code>src/services/authService.ts</code></td></tr></tbody></table><h2 id="_2-database-schema-session-impact" tabindex="-1">2. Database Schema &amp; Session Impact <a class="header-anchor" href="#_2-database-schema-session-impact" aria-label="Permalink to &quot;2. Database Schema &amp; Session Impact&quot;">​</a></h2><ul><li><strong>PostgreSQL <code>users</code>:</strong> Updates <code>password_hash</code> (BCrypt cost 12) and <code>last_password_change</code> (<code>TIMESTAMPTZ</code>).</li><li><strong>PostgreSQL <code>user_refresh_tokens</code>:</strong> Stamping <code>last_password_change = Instant.now()</code> invalidates refresh tokens issued prior to the change on other devices at their next refresh attempt while keeping the caller&#39;s active in-memory <code>accessToken</code> usable (no forced logout of the active browser tab).</li><li><strong>PostgreSQL <code>audit_logs</code>:</strong> Appends <code>AuditAction.PASSWORD_RESET</code> / security audit entry with <code>userId</code>, <code>ipAddress</code>, and <code>userAgent</code>.</li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Authenticated Request (<code>POST /api/v1/auth/change-password</code>):</strong><ul><li>Extracts <code>userId</code> strictly from <code>@AuthenticationPrincipal AuthenticatedUser</code> (<code>401 UNAUTHORIZED</code> if token missing/expired/blacklisted).</li><li>Bean Validation enforces <code>currentPassword</code> (<code>@NotBlank</code>) and <code>newPassword</code> (<code>BR-02</code>: min 8 chars, &gt;= 1 digit).</li></ul></li><li><strong>Credential &amp; Distinctness Verification (<code>BR-02</code>, <code>BR-08</code>):</strong><ul><li>Loads <code>User</code> (<code>404 USER_NOT_FOUND</code> if missing).</li><li>Verifies <code>passwordEncoder.matches(currentPassword, user.getPasswordHash())</code>; if mismatch -&gt; <code>400 WRONG_CURRENT_PASSWORD</code>.</li><li>Checks <code>passwordEncoder.matches(newPassword, user.getPasswordHash())</code>; if identical -&gt; <code>400 SAME_AS_CURRENT_PASSWORD</code> (checked strictly <em>after</em> verifying <code>currentPassword</code> so attackers with a stolen session cannot probe password equality without knowing the current password).</li></ul></li><li><strong>Persistence &amp; Audit:</strong><ul><li>Hashes <code>newPassword</code> with BCrypt cost 12, sets <code>lastPasswordChange = Instant.now()</code>, persists <code>User</code>, writes <code>AuditLog</code>, and returns <code>200 ApiResponse&lt;Void&gt;</code>.</li><li>Note: OAuth-only users (<code>passwordHash == null</code>) are routed to <code>POST /api/v1/auth/set-password</code> on the same Security screen to establish an initial password.</li></ul></li></ol><h2 id="_4-security-ux-considerations" tabindex="-1">4. Security &amp; UX Considerations <a class="header-anchor" href="#_4-security-ux-considerations" aria-label="Permalink to &quot;4. Security &amp; UX Considerations&quot;">​</a></h2><ul><li><strong>Validation Ordering:</strong> Always verify <code>currentPassword</code> before checking <code>SAME_AS_CURRENT_PASSWORD</code> or mutating state.</li><li><strong>Client Form Hygiene:</strong> Clear all three password inputs (<code>currentPassword</code>, <code>newPassword</code>, <code>confirmPassword</code>) immediately after <code>200 OK</code> and toast localized confirmation.</li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.5</code> — Change Password</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/auth/change-password · POST /api/v1/auth/set-password</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AuthController</code> -&gt; <code>AuthServiceImpl</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code> (<code>password_hash</code>, <code>last_password_change</code>), <code>user_refresh_tokens</code>, <code>audit_logs</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-02, BR-08</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>400 WRONG_CURRENT_PASSWORD</code> / <code>SAME_AS_CURRENT_PASSWORD</code> / <code>VALIDATION_ERROR</code>, <code>401 UNAUTHORIZED</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/security/index.tsx</code>, <code>src/pages/security/components/ChangePasswordCard.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/settings/SecuritySettingsScreen.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>security.changePassword.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',15)])])}const p=t(d,[["render",r]]);export{u as __pageData,p as default};
